from pathlib import Path
p=Path(__file__).resolve().parents[1];bundle=(p/'dist/geeky-player.js').read_text()
head='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Geeky Animation Kit</title><style>*{box-sizing:border-box}body{margin:0;background:#f8f7fc;color:#34314f;font:15px/1.5 system-ui,sans-serif}main{max-width:1100px;margin:32px auto;padding:0 24px}h1{font-size:34px;letter-spacing:-1px;margin:0}p{color:#8a8098}header{margin-bottom:24px}.layout{display:grid;grid-template-columns:1.05fr 1fr;gap:24px}.stage{min-height:410px;display:flex;align-items:center;justify-content:center;background:#eeeaf8;border:1px solid #dfd8ed;border-radius:24px}#geeky{width:320px;height:320px;max-width:100%}.panel{padding:22px;background:white;border:1px solid #e2ddeb;border-radius:24px}.states{display:flex;flex-wrap:wrap;gap:8px}button,select{font:inherit;padding:9px 13px;border:1px solid #d6cde5;border-radius:12px;background:#fbfaff;color:#34314f;cursor:pointer}button:hover{background:#eee8f7}button[aria-pressed="true"]{background:#dcd1f2;border-color:#9e88c4}button:focus-visible,select:focus-visible,input:focus-visible{outline:3px solid #9e88c4;outline-offset:3px}.row{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-top:18px}label{font-size:13px;color:#7e728e}input[type=range]{width:100%;accent-color:#9e88c4}#status{background:#f3f0f8;border-radius:12px;padding:14px;font:12px/1.6 ui-monospace,monospace;white-space:pre-wrap;overflow-wrap:anywhere}.note{font-size:12px}footer{margin:28px 0;color:#8a8098;font-size:13px}@media(max-width:700px){main{margin:20px auto;padding:0 16px}.layout{grid-template-columns:1fr}.stage{min-height:300px}#geeky{width:260px;height:260px}h1{font-size:28px}}</style></head><body><main><header><h1>Geeky, ready to play.</h1><p>Original eyes. Matte frames. Nine expressive states and sixteen gaze directions.</p></header><div class="layout"><section class="stage" aria-label="Animation preview"><div id="geeky"></div></section><section class="panel"><nav class="states" aria-label="Choose animation"></nav><div class="row"><button id="pause">Pause</button><button id="resume">Resume</button><label><input id="loop" type="checkbox" checked> Loop state</label><label>Speed <select id="speed"><option value="0.5">0.5×</option><option value="1" selected>1×</option><option value="1.5">1.5×</option><option value="2">2×</option></select></label></div><div class="row"><label>Gaze <select id="gaze"><option value="">Natural</option></select></label><label>Motion <select id="reduced"><option value="system">System setting</option><option value="true">Reduced</option><option value="false">Full</option></select></label></div><div class="row"><label for="seek">Scrub (pauses motion)</label><input id="seek" type="range" min="0" max="4" step="0.01" value="0"></div><div class="row"><label>Size <select id="size"><option value="64">64 px</option><option value="128">128 px</option><option value="256">256 px</option><option value="320" selected>320 px</option></select></label><button id="snapshot">Save current SVG</button></div><p class="note">A reduced-motion preference shows a meaningful still pose. “Full” is an explicit override for testing.</p><pre id="status" aria-live="off"></pre></section></div><footer>This self-contained demo runs offline. See docs/API.md and manifest.json for integration details.</footer></main><script>'''
script='''
const labels={idle:'Curious','running-right':'Flutter right','running-left':'Flutter left',waving:'Hello',jumping:'Delight',failed:'Oops',waiting:'Waiting',running:'Orbit',review:'Closer look'};
const player=Geeky.createGeeky('#geeky',{onStateChange:update});window.demoPlayer=player;
function update(){if(typeof player==='undefined')return;let s=player.getState();document.querySelector('#status').textContent=JSON.stringify(s,null,2);document.querySelector('#loop').checked=s.loop;document.querySelectorAll('[data-state]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.state===s.state));document.querySelector('#seek').value=s.time;}
Object.entries(labels).forEach(([id,label])=>{let b=document.createElement('button');b.textContent=label;b.dataset.state=id;b.onclick=()=>{player.playState(id);update()};document.querySelector('.states').append(b)});
for(let i=0;i<16;i++){let o=document.createElement('option');o.value=i*22.5;o.textContent=`${i*22.5}°${i===0?' · up':i===4?' · right':i===8?' · down':i===12?' · left':''}`;document.querySelector('#gaze').append(o)}
document.querySelector('#pause').onclick=()=>{player.pause();update()};document.querySelector('#resume').onclick=()=>{player.resume();update()};document.querySelector('#loop').onchange=e=>{player.playState(player.getState().state,{loop:e.target.checked});update()};document.querySelector('#speed').onchange=e=>{player.setSpeed(Number(e.target.value));update()};document.querySelector('#gaze').onchange=e=>{player.gaze(e.target.value===''?null:Number(e.target.value));update()};document.querySelector('#reduced').onchange=e=>{player.setReducedMotion(e.target.value==='system'?'system':e.target.value==='true');update()};document.querySelector('#seek').oninput=e=>{player.pause().seek(Number(e.target.value));update()};document.querySelector('#size').onchange=e=>{document.querySelector('#geeky').style.width=e.target.value+'px';document.querySelector('#geeky').style.height=e.target.value+'px'};
document.querySelector('#snapshot').onclick=()=>{let a=document.createElement('a'),url=URL.createObjectURL(new Blob([player.toSVG()],{type:'image/svg+xml'}));a.href=url;a.download='Geeky-pose.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)};update();setInterval(update,300);window.addEventListener('pagehide',()=>player.pause());
'''
(p/'demo/index.html').write_text(head+bundle+script+'</script></body></html>')
mobile='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Geeky WebView</title><style>html,body{margin:0;width:100%;height:100%;background:transparent;color:#34314f;font:14px system-ui}body{display:flex;flex-direction:column;align-items:center;justify-content:center}#geeky{width:min(78vw,320px);height:min(78vw,320px)}nav{display:flex;flex-wrap:wrap;justify-content:center;gap:8px;padding:12px}button{font:inherit;border:1px solid #d6cde5;border-radius:12px;background:#f8f7fc;color:#34314f;padding:9px 14px}small{max-width:300px;text-align:center;color:#8a8098}</style></head><body><div id="geeky"></div><nav><button data-state="idle">Idle</button><button data-state="orbit">Orbit</button><button data-state="closer-look">Closer look</button><button id="pause">Pause</button><button id="resume">Resume</button></nav><small>Offline WebView example. Host commands use window.GeekyBridge.receive(command).</small><script>'''+bundle+'''
function emit(payload){const message=JSON.stringify(payload);if(typeof window.ReactNativeWebView?.postMessage==='function')window.ReactNativeWebView.postMessage(message);else if(typeof window.webkit?.messageHandlers?.geeky?.postMessage==='function')window.webkit.messageHandlers.geeky.postMessage(payload);else if(typeof window.GeekyNative?.postMessage==='function')window.GeekyNative.postMessage(message)}
const player=Geeky.createGeeky('#geeky',{onStateChange:state=>emit({type:'statechange',state})});window.mobilePlayer=player;
window.GeekyBridge={receive(command){if(typeof command==='string')command=JSON.parse(command);if(!command||typeof command.type!=='string')throw new TypeError('A command object with a type is required');switch(command.type){case'playState':player.playState(command.state,{loop:command.loop,transitionMs:command.transitionMs??180,onComplete:state=>emit({type:'complete',state})});break;case'pause':player.pause();break;case'resume':player.resume();break;case'gaze':player.gaze(command.degrees??null);break;case'reducedMotion':player.setReducedMotion(command.value);break;case'speed':player.setSpeed(command.value);break;case'seek':player.pause().seek(command.seconds);break;default:throw new RangeError('Unknown command type')}return player.getState()},getState(){return player.getState()}};
document.querySelectorAll('[data-state]').forEach(b=>b.onclick=()=>player.playState(b.dataset.state));document.querySelector('#pause').onclick=()=>player.pause();document.querySelector('#resume').onclick=()=>player.resume();emit({type:'ready',state:player.getState()});window.addEventListener('pagehide',()=>player.pause());
</script></body></html>'''
(p/'examples/mobile-webview/geeky-webview.html').write_text(mobile)
